  const sonnetWeak = sonnetApprovals.samples >= 100 && sonnetApprovals.rate < 0.85;
  return sonnetWeak || paused.totalMs > 3600000 ? opus : sonnet;
});

const drafter = H.agent('drafter').role(drafterRole).model(drafterModel).pool(pool);

